function toHex(num) {
  let rest = num < 0 ? num + 4294967296 : num;
  if (rest === 0) return '0';
  const out = [];
  while (rest > 0) {
    const d = rest % 16;
    out.push(d < 10 ? String(d) : 'abcdef'[d - 10]);
    rest = Math.floor(rest / 16);
  }
  return out.reverse().join('');
